// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.sail.SailException;
import org.junit.jupiter.api.Test;

class LmdbStoreConnectionReplayConflictTest {

	@Test
	void mapResizeConflictRemainsRetryableWhenAnAbandonedAttemptReportedCleanupFailures() {
		LmdbSailStore.MapResizeConflictException conflict = new LmdbSailStore.MapResizeConflictException(
				LmdbSailStore.MapResizeKind.VALUE_STORE, "the map grew");
		conflict.addSuppressed(new SailException("cursor close failed"));
		assertTrue(LmdbStoreConnection.isMapResizeConflict(conflict),
				"a cleanup failure of the abandoned attempt must not turn a retryable growth into a hard error");

		SailException wrapped = new SailException("wrapped", conflict);
		wrapped.addSuppressed(new IllegalStateException("outer cleanup failed"));
		assertTrue(LmdbStoreConnection.isMapResizeConflict(wrapped));

		assertFalse(LmdbStoreConnection.isMapResizeConflict(new SailException("unrelated")));
	}
}
